import React from 'react';
import { motion } from 'framer-motion';
import { useInView } from 'react-intersection-observer';
import { Github, ExternalLink, TrendingUp, Sprout, Wind, Heart, ShoppingBag } from 'lucide-react';

const Projects = () => {
  const [ref, inView] = useInView({
    triggerOnce: true,
    threshold: 0.1,
  });

  const projects = [
    {
      icon: Sprout,
      title: 'IoT-Based Smart Farmland',
      subtitle: 'Edge AI Pest Detection and Remote Irrigation Control',
      problem: 'Final Year Major Team Project - IoT-based smart agriculture system using Edge AI for real-time pest detection and automated irrigation control.',
      techStack: ['IoT', 'Edge AI', 'Sensors', 'Embedded Systems'],
      insights: 'Prevents crop damage from animal intrusion with real-time monitoring and soil moisture tracking',
      github: 'https://github.com/Bharath200404/smart-farmland',
      demo: '#',
      color: 'from-green-500 to-teal-500',
    },
    {
      icon: TrendingUp,
      title: 'Retention Analytics & Churn Prediction',
      subtitle: 'End-to-End Machine Learning Pipeline',
      problem: 'Built end-to-end churn prediction pipeline using Logistic Regression, Random Forest, and XGBoost. Improved recall to 79% using class imbalance handling.',
      techStack: ['Python', 'Scikit-learn', 'Streamlit', 'XGBoost'],
      insights: 'Performed EDA for churn drivers and built Streamlit app for real-time predictions with business retention insights',
      github: 'https://github.com/Bharath200404/churn-prediction',
      demo: '#',
      color: 'from-blue-500 to-cyan-500',
    },
    {
      icon: Wind,
      title: 'Kannada Digit Recognizer',
      subtitle: 'Computer Vision & Deep Learning',
      problem: 'Designed CNN architecture for Kannada handwritten digit recognition. Achieved 88% accuracy using custom augmentation techniques.',
      techStack: ['Python', 'TensorFlow', 'CNN', 'OpenCV', 'Albumentations'],
      insights: 'Implemented webcam-based real-time recognition system with AI/vision themed UI',
      github: 'https://github.com/Bharath200404/kannada-handwritten-digits-recognition',
      demo: '#',
      color: 'from-purple-500 to-pink-500',
    },
  ];

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, translateY: 20 },
    visible: {
      opacity: 1,
      translateY: 0,
      transition: {
        duration: 0.5,
      },
    },
  };

  return (
    <section id="projects" className="py-20 relative">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          ref={ref}
          initial="hidden"
          animate={inView ? 'visible' : 'hidden'}
          variants={containerVariants}
        >
          {/* Section Header */}
          <motion.div variants={itemVariants} className="text-center mb-16">
            <h2 className="section-title">Featured Projects</h2>
            <p className="section-subtitle max-w-2xl mx-auto">
              Showcasing innovative solutions that solve real-world problems
            </p>
          </motion.div>

          {/* Projects Grid */}
          <div className="grid md:grid-cols-2 gap-8">
            {projects.map((project) => (
              <motion.div
                key={project.title}
                variants={itemVariants}
                className="glass-card p-6 hover:scale-105 transition-transform duration-300 group"
              >
                {/* Project Header */}
                <div className="flex items-start justify-between mb-4">
                  <div className={`p-3 rounded-lg bg-gradient-to-r ${project.color}`}>
                    <project.icon className="w-8 h-8 text-white" />
                  </div>
                  <div className="flex gap-2">
                    <a
                      href={project.github}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="p-2 rounded-lg bg-dark-800 hover:bg-dark-700 transition-colors"
                      aria-label="View on GitHub"
                    >
                      <Github className="w-5 h-5 text-gray-400 hover:text-white" />
                    </a>
                    <a
                      href={project.demo}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="p-2 rounded-lg bg-dark-800 hover:bg-dark-700 transition-colors"
                      aria-label="View Live Demo"
                    >
                      <ExternalLink className="w-5 h-5 text-gray-400 hover:text-white" />
                    </a>
                  </div>
                </div>

                {/* Project Content */}
                <h3 className="text-xl font-semibold mb-3 group-hover:text-accent-400 transition-colors">
                  {project.title}
                </h3>

                <p className="text-gray-400 mb-4 text-sm leading-relaxed">
                  {project.problem}
                </p>

                {/* Tech Stack */}
                <div className="flex flex-wrap gap-2 mb-4">
                  {project.techStack.map((tech) => (
                    <span
                      key={tech}
                      className="px-3 py-1 text-xs rounded-full bg-dark-800 text-gray-300 border border-white/10"
                    >
                      {tech}
                    </span>
                  ))}
                </div>

                {/* Key Insights */}
                <div className="p-3 rounded-lg bg-accent-400/5 border border-accent-400/10">
                  <p className="text-sm text-accent-400">
                    <span className="font-semibold">Key Result:</span> {project.insights}
                  </p>
                </div>
              </motion.div>
            ))}
          </div>

          {/* Call to Action */}
          <motion.div variants={itemVariants} className="mt-12 text-center">
            <a
              href="https://github.com/bharath"
              target="_blank"
              rel="noopener noreferrer"
              className="btn-primary inline-flex items-center gap-2"
            >
              <Github className="w-5 h-5" />
              View All Projects on GitHub
            </a>
          </motion.div>
        </motion.div>
      </div>
    </section>
  );
};

export default Projects;
